  AND wo.`id` IS NULL AND pm.`id` IS NULL AND lc.`id` IS NULL
  AND (
    e_stale.`notes` LIKE 'EXAMPLE ROW%'
    OR (e_stale.`serial_number` LIKE 'SN-%' AND e_stale.`frame_no` IS NOT NULL AND e_stale.`frame_no` != '')
    OR e_stale.`brand` = 'CATERPILAR'
    OR e_stale.`model` = 'TOYOTA LC'
  );

-- 5. Normalize any remaining user-created custom rows that have active work orders/PMs
UPDATE `equipment`
SET `serial_number` = IF(`serial_number` LIKE 'SN-%' AND `frame_no` IS NOT NULL AND `frame_no` != '', `frame_no`, `serial_number`),
    `brand` = IF(`brand` = 'CATERPILAR', 'CATERPILLAR', `brand`),
    `model` = IF(`model` = 'TOYOTA LC', 'LAND CRUISER HARD TOP', `model`)
WHERE (`serial_number` LIKE 'SN-%' AND `frame_no` IS NOT NULL AND `frame_no` != '')
   OR `brand` = 'CATERPILAR'
   OR `model` = 'TOYOTA LC';
